 host.innerHTML=groups.map((group,gi)=>{const H=310,L=38,R=15,T=25,B=65,ph=H-T-B,step=(W-L-R)/group.length,x=i=>L+(i+.5)*step,y=v=>T+ph/2-v/max*ph/2,zero=y(0);let svg=`<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px" role="img" aria-label="R bulanan setelah risk reward"><defs><linearGradient id="rp${gi}" x2="0" y2="1"><stop stop-color="#59e1b3"/><stop offset="1" stop-color="#187c5c"/></linearGradient><linearGradient id="rn${gi}" x2="0" y2="1"><stop stop-color="#ff90a8"/><stop offset="1" stop-color="#aa3c61"/></linearGradient></defs>`;
 for(let i=0;i<5;i++){const v=max*(1-i/2),yy=y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#344b61" stroke-dasharray="${i===2?'0':'2 5'}"/><text x="${L-6}" y="${yy+3}" text-anchor="end" fill="#91abc4" font-size="8">${compact(v)} R</text>`;}
 group.forEach((v,i)=>{const xx=L+i*step;if(i===0||v.key.slice(0,4)!==group[i-1].key.slice(0,4))svg+=`<line x1="${xx}" x2="${xx}" y1="${T-8}" y2="${H-B+3}" stroke="#91a6c1" stroke-width="1" opacity=".7"/><text x="${xx+3}" y="${T-13}" fill="#b9cfe3" font-size="9">${v.key.slice(0,4)}</text>`;if(v.r!==null&&Math.abs(v.r)>1e-9){const yy=y(v.r);svg+=`<rect data-r-bar="${v.key}" data-r="${v.r}" x="${xx+.5}" y="${Math.min(yy,zero)}" width="${Math.max(.7,step-1)}" height="${Math.abs(zero-yy)}" fill="url(#${v.r>0?'rp':'rn'}${gi})"/>`;}else svg+=`<line x1="${xx+1}" x2="${xx+step-1}" y1="${zero}" y2="${zero}" stroke="${v.r===null?'#d7b963':'#8eabc3'}" stroke-width="${v.r===null?3:1}"/>`;svg+=`<text data-r-label="${v.key}" transform="translate(${x(i)},${H-B+16}) rotate(-55)" text-anchor="end" fill="#a9bfd7" font-size="9">${months[Number(v.key.slice(5))-1].slice(0,3)}</text><rect data-r-hover="${v.key}" x="${xx}" y="${T}" width="${step}" height="${ph}" fill="transparent" tabindex="0"/>`;});return svg+'</svg>';}).join('');
 for(const el of host.querySelectorAll('[data-r-hover]')){const v=values.find(v=>v.key===el.dataset.rHover),ratio=v.rr.ratio===null?'—':rrFormat517.format(v.rr.ratio);bindTip(el,`<b>${monthTitle(v.key)} · ${esc(state.pair)}</b>TP ${v.tp} · SL ${v.sl}<br>RR 6 bulan ${v.rr.ratio===null?'belum tersedia':'1 : '+ratio}<br>${v.r===null?'Perlu trade TP dan SL pada periode RR.':`(TP ${v.tp} × ${ratio}) − SL ${v.sl} = <strong class="${resultClass(v.r)}">${signedR(v.r)} R</strong>`}<br>${monthTitle(v.rr.start.slice(0,7))} – ${monthTitle(v.key)} · ${v.rr.count} trade acuan`);el.onclick=()=>showDetail(v.rows,monthTitle(v.key)+' · R berbobot RR',el);}
 const known=values.filter(v=>v.r!==null),total=known.reduce((s,v)=>s+v.r,0),missing=values.filter(v=>v.r===null).length;
 footer.innerHTML=`<span>Total R ${missing?'terhitung · ':''}periode terpilih <b class="${known.length?resultClass(rrTrunc517(total)):'neutral'}" data-total-r="${known.length?total:''}">${known.length?signedR(total)+' R':'—'}</b></span><span>${values.length} bulan${missing?' · '+missing+' bulan belum ada RR, belum termasuk total':''}</span>`;
